//! Opt-in authored FIX on the existing retained daemon; no sibling compiler host.
use super::{protocol,transport,selected_report_wire as wire};use crate::{native_fix::{self,Codemod},request::Command};use std::{error::Error,io,path::PathBuf};
fn invalid(text:&str)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,text)}
pub(super)fn qualify(request:&native_fix::BatchRequest)->io::Result<()>{request.qualify()?;super::build_admission::validate(&request.build).map_err(io::Error::other)?;super::generation::validate_cache(&request.build)}
fn invocation(args:&[String])->Result<native_fix::BatchRequest,Box<dyn Error>>{
 let(mut root,mut prefixes,mut apply,mut tests,mut drop_declared)=(None,Vec::new(),false,false,false);let mut at=0;while let Some(arg)=args.get(at){at+=1;match arg.as_str(){"--workspace"=>{let value=args.get(at).ok_or_else(||invalid("FIX workspace value missing"))?;at+=1;if root.replace(PathBuf::from(value)).is_some(){return Err(invalid("duplicate FIX workspace").into())}},"--path"=>{let value=args.get(at).ok_or_else(||invalid("FIX path value missing"))?;at+=1;prefixes.push(value.clone());},"--apply"=>apply=true,"--tests"=>tests=true,"--drop-declared"=>drop_declared=true,_=>return Err(invalid("unsupported or repeated native FIX option").into())}}
 // Match legacy drop-declared precedence over tests.
let root=root.filter(|root|root.is_absolute()).ok_or_else(||invalid("native FIX needs absolute workspace"))?;let root=std::fs::canonicalize(root)?;let cache=std::fs::canonicalize(crate::request::client_cache_root()?)?;
 let Command::Build(build)=crate::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()])?else{return Err(invalid("FIX requires real PrepareQuery").into())};let mut build=*build;build.no_cache=true;build.exact_inputs=true;build.progress_enabled=false;build.workers=2;build.timeout_seconds=Some(300);build.engine_template=None;build.bootstrap_catalog=false;build.cache_root=Some(cache);
 use crate::policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q};let questions=if drop_declared{vec![Q::SemReads,Q::Tracked]}else if tests{vec![Q::TrackedTests]}else{vec![Q::Tracked]};let roots=["code","doc/rewrite","interface","maps","modular_chomp","tgui"];
 build.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.clone(),recursive_roots:roots.map(|p|root.join(p)).to_vec(),configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:questions,..Default::default()});let request=native_fix::BatchRequest{build,codemod:if drop_declared{Codemod::TrackedDropDeclared}else if tests{Codemod::TrackedTests}else{Codemod::Tracked},prefixes,apply};qualify(&request)?;Ok(request)
}
pub fn run_cli(args:&[String])->Result<(),Box<dyn Error>>{let request=invocation(args)?;let workspace=request.build.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap();let root=workspace.root.clone();let cache=request.build.cache_root.as_ref().unwrap().clone();let prefixes=request.prefixes.clone();let mode=request.codemod;let apply=request.apply;let mut stream=super::connect_generation()?;transport::set_timeout(&mut stream,transport::BUILD_DEADLINE)?;protocol::send(&mut stream,&protocol::Request::NativeFix(request))?;wire::receive_fix(&mut stream,&cache,&root,&prefixes,mode,apply)?.publish(&mut io::stdout().lock()).map_err(Into::into)}

